// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint t, uint amount) public {
        // Bound block timestamp to a reasonable range
        vm.assume(t >= 1000000 && t <= 2000000);
        vm.assume(amount == 10 ether);

        // First call: warp to time t, set pastBlockTime to t + 1
        vm.warp(t);
        vm.deal(address(this), amount);
        (bool ok1, ) = address(c).call{value: amount}("");
        if (ok1) {
            // Second call: warp to exactly pastBlockTime (t+1)
            // In correct contract, this should revert (require(>)), in buggy it succeeds
            vm.warp(t + 1);
            vm.deal(address(this), amount);
            (bool ok2, ) = address(c).call{value: amount}("");
            // Rule: second call must revert because timestamp equals pastBlockTime
            assertTrue(!ok2);
        }
    }
}

